'use strict';

var isArray = require( '@stdlib/assert/is-array' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var defineProperty = require( '@stdlib/utils/define-property' );
var SearchSymbol = require( './../lib' );

function MySearchable() {}
defineProperty(MySearchable.prototype, SearchSymbol, {
    'value': function(str) {
        return str.indexOf('foo'); // returns index of 'foo' or -1
    },
    'configurable': true
});

function customSearch(str) {
    return str.indexOf('foo'); // example
}

var str = 'foo bar';

var myObj = {
    [SearchSymbol](str) {
        return str.indexOf('foo');
    }
};

console.log('foo bar'.search(myObj)); // 0
console.log('bar baz'.search(myObj)); // -1
